<?php require_once "_bootstrap.php"; $stmt = $pdo->prepare("SELECT r.*, c.code, c.title FROM student_results r INNER JOIN courses c ON c.id = r.course_id WHERE r.student_id = :id AND r.status = 'Published' ORDER BY r.academic_year DESC, c.code"); $stmt->execute(["id" => $student["id"]]); $results = $stmt->fetchAll(); $e = static fn ($value): string => htmlspecialchars((string) $value, ENT_QUOTES, "UTF-8"); ?>
<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Results</title><link rel="stylesheet" href="../assets/style.css"></head><body><header class="topbar"><a href="index.php">RAVINE ACADEMIC</a><nav><a href="index.php">Dashboard</a><a href="courses.php">Courses</a><a href="https://localhost/RAO_HBMIS/auth/login.php">Hostel</a><a href="../auth/logout.php">Log out</a></nav></header><main class="shell"><a href="index.php">&larr; Dashboard</a><p class="eyebrow">ACADEMIC RECORD</p><h1>Published results</h1><section class="panel"><table><thead><tr><th>Course</th><th>Title</th><th>Academic year</th><th>Score</th><th>Grade</th></tr></thead><tbody><?php if (!$results): ?><tr><td colspan="5">No published results available.</td></tr><?php else: foreach ($results as $result): ?><tr><td><?php echo $e($result["code"]); ?></td><td><?php echo $e($result["title"]); ?></td><td><?php echo $e($result["academic_year"]); ?></td><td><?php echo $e($result["score"]); ?>%</td><td><strong><?php echo $e($result["grade"]); ?></strong></td></tr><?php endforeach; endif; ?></tbody></table></section></main></body></html>
